body { font-family: system-ui, sans-serif; padding: 20px; }

.halaman {
  display: grid;
  grid-template-columns: 140px 1fr;
  grid-template-areas:
    "kepala kepala"
    "sisi   isi"
    "kaki   kaki";
  gap: 10px;
  margin-bottom: 30px;
}

.halaman > * {
  padding: 16px;
  border: 2px solid #201e1d;
  background: #fff;
}

header { grid-area: kepala; background: #c67139; color: #fff; }
aside  { grid-area: sisi;   background: #e1eecc; }
main   { grid-area: isi; }
footer { grid-area: kaki;   background: #ebddc5; }

.galeri {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 12px;
}

.galeri > div {
  padding: 24px;
  text-align: center;
  background: #ffe1d0;
  border: 2px solid #201e1d;
}

.penuh {
  grid-column: 1 / -1;
  background: #e1eecc;
}

body { font-family: system-ui, sans-serif; padding: 30px; }

.tombol {
  padding: 12px 24px;
  border: 2px solid #201e1d;
  background: #fff;
  cursor: pointer;
  /* Ditulis di keadaan normal agar mulus dua arah */
  transition: transform 0.2s ease, background 0.2s ease;
}

.tombol:hover {
  transform: translateY(-3px);
  background: #ffe1d0;
}

.kartu {
  max-width: 280px;
  margin-top: 24px;
  padding: 20px;
  border: 2px solid #201e1d;
  background: #fff;
  box-shadow: 0 0 0 #201e1d;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}

.kartu:hover {
  transform: translate(-4px, -4px);
  box-shadow: 6px 6px 0 #201e1d;
}

@keyframes denyut {
  0%   { transform: scale(1); }
  50%  { transform: scale(1.4); }
  100% { transform: scale(1); }
}

.titik {
  width: 24px;
  height: 24px;
  margin-top: 30px;
  border-radius: 50%;
  background: #c67139;
  animation: denyut 1.4s ease-in-out infinite;
}

/* Hormati pengguna yang memilih mengurangi gerakan */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

*, *::before, *::after { box-sizing: border-box; }

body {
  font-family: system-ui, sans-serif;
  padding: 20px;
  margin: 0;
}

/* Melar dalam batas aman — menggantikan beberapa breakpoint */
h1 {
  font-size: clamp(1.25rem, 5vw, 2.5rem);
}

/* Responsif tanpa satu pun media query */
.galeri {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
  gap: 12px;
}

/* Mobile-first: dasar untuk layar sempit */
.kartu {
  padding: 16px;
  border: 2px solid #201e1d;
  background: #e1eecc;
  font-size: 0.9rem;
}

@media (min-width: 600px) {
  .kartu {
    padding: 28px;
    font-size: 1rem;
    background: #ffe1d0;
  }
}

@media (min-width: 900px) {
  .kartu {
    padding: 40px;
    font-size: 1.125rem;
  }
}

:root {
  --warna-utama: #c67139;
  --warna-teks: #201e1d;
  --warna-latar: #f5ead8;

  --jarak-2: 16px;
  --jarak-3: 24px;
  --radius: 16px;
  --garis: 2px solid var(--warna-teks);
}

body {
  font-family: system-ui, sans-serif;
  background: var(--warna-latar);
  color: var(--warna-teks);
  padding: var(--jarak-3);
}

.kartu {
  --aksen: var(--warna-utama);

  max-width: 320px;
  margin-bottom: var(--jarak-2);
  padding: var(--jarak-3);
  border: var(--garis);
  border-left: 8px solid var(--aksen);
  border-radius: var(--radius);
  background: #fff;
}

.kartu h2 {
  margin: 0 0 var(--jarak-2);
  color: var(--aksen);
}

/* Cukup timpa satu variabel */
.kartu.hijau {
  --aksen: #7a8a5e;
}

