body {
  font-family: system-ui, sans-serif;
  background: #f5ead8;
  padding: 32px;
}

/* Foto persegi + radius 50% = lingkaran.
   object-fit mencegah gambar gepeng saat dipotong. */
.foto-profil {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  object-fit: cover;
  border: 3px solid #201e1d;
}

.kartu {
  max-width: 340px;
  margin-top: 24px;
  padding: 20px;
  background: #fff;
  border-left: 8px solid #c67139;
  border-radius: 16px;
  /* Dua lapis bayangan: satu tipis dekat, satu lebar jauh */
  box-shadow:
    0 1px 2px rgb(32 30 29 / 10%),
    0 8px 24px rgb(32 30 29 / 12%);
}

.kartu h2 { margin-top: 0; font-size: 1.125rem; }

.tombol {
  display: inline-block;
  padding: 8px 18px;
  border-radius: 999px;
  background: #c67139;
  color: #fff;
  text-decoration: none;
}

/* outline tidak memakan ruang, jadi tata letak tidak bergeser */
.tombol:hover { outline: 2px solid #201e1d; outline-offset: 2px; }
.tombol:focus-visible { outline: 3px solid #201e1d; outline-offset: 3px; }

body {
  font-family: system-ui, sans-serif;
  background: #f5ead8;
  padding: 24px;
  max-width: 640px;
}

/* Menu mendatar: bulatan DAN padding bawaan harus dibuang */
.menu ul {
  list-style: none;
  padding: 0;
  margin: 0 0 24px;
  display: flex;
  gap: 16px;
}

.menu a {
  text-decoration: none;
  font-weight: 600;
}

/* Daftar keahlian: bulatannya diwarnai, bukan dihapus */
.keahlian { padding-left: 20px; }
.keahlian li::marker { color: #c67139; }

table {
  border-collapse: collapse;
  width: 100%;
}

caption {
  text-align: left;
  font-weight: 700;
  padding-bottom: 8px;
}

th, td {
  padding: 10px 12px;
  text-align: left;              /* th bawaannya rata tengah */
  border-bottom: 1px solid #dcd3c4;
}

tbody tr:nth-child(even) { background: #f9f4ed; }
tbody tr:hover { background: #ffe1d0; }

/* Urutan wajib LVHA — LoVe HAte */
a:link    { color: #8c491a; }
a:visited { color: #643312; }
a:hover   { color: #c67139; }
a:active  { color: #402310; }
